import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.ShopConfig;
import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.money.Money;
import com.wolinski.shop.notifications.api.MailTransport;
import com.wolinski.shop.orders.api.OrderFacade;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;

class CancellationNotificationsTest {

    @Test
    void cancellingAnOrderMailsTheCustomerOnce() {
        try (var shop = context()) {
            RecordingMailTransport mail = shop.getBean(RecordingMailTransport.class);
            shop.getBean(CustomerFacade.class).register("c-1", "anna@shop.example");
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            orders.cancel(id);

            assertEquals(1, mail.sent.size());
            Sent sent = mail.sent.get(0);
            assertEquals("anna@shop.example", sent.address());
            assertTrue(sent.subject().contains(id), sent.subject());
        }
    }

    @Test
    void cancellingTwiceMailsOnlyOnce() {
        try (var shop = context()) {
            RecordingMailTransport mail = shop.getBean(RecordingMailTransport.class);
            shop.getBean(CustomerFacade.class).register("c-1", "anna@shop.example");
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            orders.cancel(id);
            orders.cancel(id);

            assertEquals(1, mail.sent.size());
        }
    }

    @Test
    void aCustomerWithoutARegisteredAddressIsNotMailed() {
        try (var shop = context()) {
            RecordingMailTransport mail = shop.getBean(RecordingMailTransport.class);
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-unknown", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            orders.cancel(id);

            assertEquals(0, mail.sent.size());
            assertEquals("CANCELLED", orders.summary(id).status());
        }
    }

    private static AnnotationConfigApplicationContext context() {
        return new AnnotationConfigApplicationContext(ShopConfig.class, RecordingMailConfig.class);
    }

    record Sent(String address, String subject, String body) {
    }

    static class RecordingMailTransport implements MailTransport {

        final List<Sent> sent = new ArrayList<>();

        @Override
        public void deliver(String address, String subject, String body) {
            sent.add(new Sent(address, subject, body));
        }
    }

    @Configuration
    static class RecordingMailConfig {

        @Bean
        @Primary
        RecordingMailTransport recordingMailTransport() {
            return new RecordingMailTransport();
        }
    }
}
}
